import { createHash } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';

const DESIGN_SYSTEM_SOURCE_FILES = [
    'frontend/design-system/catalogEntry.js',
    'frontend/design-system/catalog.js',
    'frontend/design-system/themeCatalogModel.js',
    'frontend/js/selectCombobox.js',
    'frontend/themes/manifest.json',
];

export function designSystemSourceHash(root) {
    const hash = createHash('sha256');
    for (const file of DESIGN_SYSTEM_SOURCE_FILES) {
        hash.update(file);
        hash.update('\0');
        hash.update(readFileSync(resolve(root, file)));
        hash.update('\0');
    }
    return hash.digest('hex');
}

export function designSystemBundlePath(root) {
    return resolve(root, 'frontend/design-system/catalog.bundle.js');
}

export function designSystemBundleOptions(root) {
    const sourceHash = designSystemSourceHash(root);
    return {
        entryPoints: [resolve(root, 'frontend/design-system/catalogEntry.js')],
        outfile: designSystemBundlePath(root),
        bundle: true,
        write: false,
        format: 'iife',
        platform: 'browser',
        target: 'es2020',
        legalComments: 'none',
        banner: {
            js: `/* Generated by scripts/build-design-system.mjs. Source hash: ${sourceHash}. Do not edit directly. */`,
        },
    };
}
